import { GoogleGenAI } from "@google/genai";
import { AnalysisResult, FashionItem } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Using the flagship Gemini 3 Pro model for advanced reasoning and visual identification
const MODEL_PRO = "gemini-3-pro-preview";

const SYSTEM_INSTRUCTION = "Szerep: Divat-detektív. Feladat: Ruhadarabok azonosítása Google keresés segítségével. Elsőbbség: Hiteles források (Getty Images, Vogue, Red Carpet Fashion Awards, WornOnTV). Csak divatcikkekkel foglalkozz. Ha az azonosítás sikertelen, térj vissza 'Ismeretlen' értékkel.";

const PROMPT_TEXT = `Azonosítsd a képen látható divatcikkeket.

SZABÁLYOK A MÁRKÁHOZ ÉS A MEGBÍZHATÓSÁGHOZ:
1. MOZI/TV JELMEZEK: Ha a kép filmből vagy sorozatból van, és a ruha egyedi jelmez, a márka legyen "[Film címe] jelmezterv".
2. ISMERETLEN MÁRKÁK: Ha nem tudod biztosan a márkát, használd az "Ismeretlen" megjelölést.
3. MEGBÍZHATÓSÁGI SZINTEK:
   - **PERFECT**: 95-100% Bizonyosság. Vizuális egyezés szükséges retail/editorial oldalakról.
   - **HIGH**: 80-94% Bizonyosság. Erős vizuális bizonyíték.
   - **LOW**: Akkor használd, ha a márka "Ismeretlen".

FOLYAMAT:
1. VIZUÁLIS LELTÁR: Színek, anyagok, szabás.
2. KERESÉS: Generálj specifikus keresési lekérdezéseket a brand azonosításához.
3. MEGERŐSÍTÉS: Találd meg a pontos terméket.
4. KÉP: 'Perfect' egyezés esetén keress egy tiszta termékkép vagy kiváló minőségű editorial kép URL-t.

VÁLASZ: RAW JSON formátum.
Struktúra: { items: [{ category, brand, confidence, description, materials, imageUrl, shoppingQuery }], styleSummary }`;

async function generateWithModel(model: string, base64Image: string, mimeType: string) {
    const response = await ai.models.generateContent({
        model: model,
        contents: {
            parts: [
                { inlineData: { data: base64Image, mimeType: mimeType } },
                { text: PROMPT_TEXT },
            ],
        },
        config: {
            tools: [{ googleSearch: {} }],
            systemInstruction: SYSTEM_INSTRUCTION,
            temperature: 0.1, 
            thinkingConfig: { thinkingBudget: 32768 }, // Max budget for Pro
            maxOutputTokens: 16384,
        },
    });
    return response;
}

function processResponse(response: any): AnalysisResult {
    if (!response || !response.text) {
        throw new Error("Nincs válasz az AI modelltől.");
    }

    let textResponse = response.text;

    try {
        const firstBrace = textResponse.indexOf('{');
        const lastBrace = textResponse.lastIndexOf('}');

        if (firstBrace !== -1 && lastBrace !== -1) {
            textResponse = textResponse.substring(firstBrace, lastBrace + 1);
        }

        const parsedResult = JSON.parse(textResponse) as AnalysisResult;

        if (parsedResult.styleSummary === "REJECT_NO_FASHION") {
            throw new Error("Nem észlelhető ruházat vagy ember a képen.");
        }

        parsedResult.sourceUrls = [];

        if (!parsedResult.items || !Array.isArray(parsedResult.items)) {
            parsedResult.items = [];
        } else {
            parsedResult.items = parsedResult.items.map((item: any) => {
                let materials: string[] = [];
                if (Array.isArray(item.materials)) {
                    materials = item.materials;
                } else if (typeof item.materials === 'string') {
                    materials = item.materials.split(',').map((s: string) => s.trim());
                }

                let brand = item.brand || "Ismeretlen";
                let confidence = item.confidence || "Low";

                // Map English confidence to Hungarian for internal logic consistency if needed, 
                // but keep original keys for the UI mapping
                if (brand.toLowerCase() === 'unknown' || brand.toLowerCase() === 'generic' || brand.toLowerCase() === 'ismeretlen') {
                    brand = 'Ismeretlen';
                    confidence = 'Low';
                }

                return {
                    category: item.category || "Tárgy",
                    brand: brand,
                    confidence: confidence,
                    description: item.description || "",
                    materials: materials,
                    imageUrl: item.imageUrl || undefined,
                    shoppingQuery: item.shoppingQuery || ""
                } as FashionItem;
            });
        }

        return parsedResult;

    } catch (error) {
        console.error("JSON Parse Error:", error);
        throw new Error("Hiba történt az elemzés feldolgozása során. Próbáld újra.");
    }
}

export const analyzeFashionImage = async (base64Image: string, mimeType: string): Promise<AnalysisResult> => {
  try {
    const response = await generateWithModel(MODEL_PRO, base64Image, mimeType);
    return processResponse(response);
  } catch (error: any) {
    if (error.message && error.message.includes("Nem észlelhető")) throw error;
    throw new Error(error.message || "Az elemzés jelenleg nem elérhető.");
  }
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { ImageInput } from './components/ImageInput';
import { AnalysisResult } from './components/AnalysisResult';
import { LoadingOverlay } from './components/LoadingOverlay';
import { analyzeFashionImage } from './services/geminiService';
import { AnalysisResult as ResultType, ImageFile } from './types';
import { RefreshCcw, X, AlertTriangle } from 'lucide-react';
import { LogoIcon } from './components/LogoIcon';

const App: React.FC = () => {
  const [currentImage, setCurrentImage] = useState<ImageFile | null>(null);
  const [analysisResult, setAnalysisResult] = useState<ResultType | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isDelayed, setIsDelayed] = useState(false);

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isLoading && progress >= 99) {
      timer = setTimeout(() => {
        setIsDelayed(true);
      }, 2000); 
    }
    return () => clearTimeout(timer);
  }, [progress, isLoading]);

  const handleImageSelected = (base64: string, mimeType: string, preview: string) => {
    setCurrentImage({ base64, mimeType, preview });
    setAnalysisResult(null);
    setError(null);
  };

  const handleScan = async () => {
    if (!currentImage) return;

    setIsLoading(true);
    setIsDelayed(false);
    setError(null);
    setProgress(0);

    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 99) return 99;
        let increment = prev < 30 ? 2.0 : prev < 85 ? 0.2 : 0.015;
        const next = prev + increment;
        return next > 99 ? 99 : next;
      });
    }, 100);

    try {
      const minTimePromise = new Promise(resolve => setTimeout(resolve, 15000));
      const aiPromise = analyzeFashionImage(currentImage.base64, currentImage.mimeType);

      const [result] = await Promise.all([aiPromise, minTimePromise]);

      setAnalysisResult(result);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "Váratlan hiba történt.");
    } finally {
      clearInterval(progressInterval);
      if (!error) {
        setTimeout(() => {
            setIsLoading(false);
            setIsDelayed(false);
        }, 500);
      } else {
        setIsLoading(false);
        setIsDelayed(false);
      }
    }
  };

  const handleReset = () => {
    setCurrentImage(null);
    setAnalysisResult(null);
    setError(null);
    setProgress(0);
    setIsDelayed(false);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col">
      <Header />

      <main 
        className={`max-w-screen-md mx-auto px-6 pb-0 space-y-12 flex-grow w-full flex flex-col items-center ${!currentImage ? 'justify-center' : 'pt-10'}`}
      >

        {!currentImage && (
          <div className="text-center space-y-6">
            <h2 className="text-4xl md:text-5xl text-black leading-tight flex flex-col md:block items-center justify-center gap-2">
              <span className="font-serif tracking-tighter inline-block transform scale-y-110">Szkenneld</span>
              <span className="font-serif tracking-tighter inline-block transform scale-y-110 px-2">a lookot <span>&</span> tudd meg a</span>
              <span className="font-serif tracking-tighter inline-block transform scale-y-110">Márkát.</span>
            </h2>
            <p className="text-black font-normal max-w-sm mx-auto">
              Tölts fel egy képet, és azonosítjuk a márkákat, stílusokat és minden apró részletet.
            </p>
          </div>
        )}

        <div className="relative w-full">
          {!currentImage ? (
            <ImageInput onImageSelected={handleImageSelected} />
          ) : (
            <div className="w-fit mx-auto relative shadow-xl">
              <img 
                src={currentImage.preview} 
                alt="Uploaded analysis" 
                className="w-auto h-auto max-h-[60vh] max-w-full object-contain"
              />

              {isLoading && <LoadingOverlay progress={Math.floor(progress)} showDelayedMessage={isDelayed} />}

              {!isLoading && (
                 <button 
                 onClick={handleReset}
                 className="absolute top-4 right-4 p-2 bg-white text-black rounded-full shadow-lg hover:bg-black hover:text-white transition-all duration-300 z-10"
                 aria-label="Kép eltávolítása"
               >
                 <X className="w-5 h-5" />
               </button>
              )}
            </div>
          )}
        </div>

        {error && (
          <div className="bg-gray-50 border-l-2 border-red-500 p-6 flex items-start gap-4 w-full">
            <AlertTriangle className="w-5 h-5 text-red-500 shrink-0" />
            <div>
              <p className="font-serif text-black font-medium">Sikertelen elemzés</p>
              <p className="text-sm text-gray-500 mt-1">{error}</p>
              <button 
                onClick={() => setCurrentImage(null)} 
                className="mt-4 text-xs font-bold uppercase tracking-widest text-black hover:underline"
              >
                Újrakezdés
              </button>
            </div>
          </div>
        )}

        {analysisResult && !isLoading && (
          <div className="space-y-4 w-full">
            <AnalysisResult result={analysisResult} />

            <p className="text-[10px] text-gray-400 font-sans font-light text-center mt-8">
                Az AI hibázhat. Kérjük, ellenőrizd a fontos információkat.
            </p>

            <div className="h-32"></div>

            <button 
                onClick={handleReset}
                className="w-full py-5 bg-black text-white font-medium text-sm uppercase tracking-widest hover:bg-gray-900 transition-colors flex items-center justify-center gap-5"
            >
                <RefreshCcw className="w-4 h-4" />
                Új Look Szkennelése
            </button>
          </div>
        )}

      </main>

      {(!currentImage || (analysisResult && !isLoading)) && (
        <footer className="w-full py-8 text-center bg-white">
            <p className="text-[10px] text-gray-400 font-sans uppercase tracking-widest">
                Készítette: <a href="https://kisskatal.in" target="_blank" rel="noopener noreferrer" className="hover:text-black transition-colors font-medium underline decoration-dotted underline-offset-4">kisskatal.in</a>
            </p>
        </footer>
      )}

      {currentImage && !analysisResult && !isLoading && (
        <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 p-6 z-40 animate-in slide-in-from-bottom-full duration-500">
             <div className="max-w-screen-md mx-auto">
                <button 
                  onClick={handleScan}
                  className="w-full py-4 bg-black text-white font-medium text-sm uppercase tracking-widest hover:bg-gray-900 transition-all shadow-lg flex items-center justify-center gap-6"
                >
                  <LogoIcon className="w-5 h-5" />
                  Look Szkennelése
                </button>
             </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AnalysisResult as ResultType } from '../types';
import { Check, AlertTriangle, Star } from 'lucide-react';
import { LogoIcon } from './LogoIcon';

interface AnalysisResultProps {
  result: ResultType;
}

const ImageWithFallback = ({ src, alt, className }: { src: string, alt: string, className: string }) => {
    const [loaded, setLoaded] = useState(false);
    const [error, setError] = useState(false);
    if (error) return null;
    return (
        <img 
            src={src} 
            alt={alt} 
            className={`${className} transition-opacity duration-500 ${loaded ? 'opacity-100' : 'opacity-0'}`}
            onLoad={() => setLoaded(true)}
            onError={() => setError(true)}
        />
    );
};

export const AnalysisResult: React.FC<AnalysisResultProps> = ({ result }) => {
  const sortedItems = [...result.items].sort((a, b) => {
    const scores: Record<string, number> = { 'Perfect': 4, 'High': 3, 'Medium': 2, 'Low': 1 };
    const scoreA = scores[a.confidence] || 0;
    const scoreB = scores[b.confidence] || 0;
    if (scoreA !== scoreB) return scoreB - scoreA;
    const isGeneric = (str: string) => {
        const s = (str || '').toLowerCase();
        return s.includes('unknown') || s.includes('unidentified') || s.includes('generic') || s === 'n/a' || s.includes('ismeretlen');
    };
    if (isGeneric(a.brand) && !isGeneric(b.brand)) return 1;
    if (!isGeneric(a.brand) && isGeneric(b.brand)) return -1;
    return 0;
  });

  const getConfidenceText = (conf: string) => {
    const c = conf.toLowerCase();
    if (c === 'perfect') return 'Tökéletes';
    if (c === 'high') return 'Magas';
    if (c === 'medium') return 'Közepes';
    return 'Alacsony';
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-8 duration-700">

      <div className="relative overflow-hidden bg-black text-white p-8 shadow-2xl mb-2">
        <div className="absolute top-8 right-8 opacity-20">
            <LogoIcon className="w-20 h-20 text-white" />
        </div>
        <h3 className="text-[10px] font-medium uppercase tracking-widest text-gray-400 mb-4 flex items-center gap-2">
          Vizuális Elemzés
        </h3>
        <p className="text-[1.1rem] font-serif font-light leading-relaxed italic text-gray-100">
          "{result.styleSummary}"
        </p>
      </div>

      <div className="space-y-4 pb-6 mt-2">
        <h3 className="text-xl font-sans font-normal text-gray-400 px-1">
          Azonosított Darabok
        </h3>

        {sortedItems.map((item, index) => {
          const isPerfectMatch = (item.confidence || '').toLowerCase() === 'perfect';
          const isHighConfidence = (item.confidence || '').toLowerCase() === 'high';

          return (
            <div 
              key={index} 
              className={`bg-white border-l-2 border-y border-r border-gray-100 p-6 shadow-sm hover:shadow-md transition-all duration-500 ${
                  isPerfectMatch ? 'border-l-black' : 'border-l-gray-200'
              }`}
            >
              <div className="flex flex-col gap-4">
                <div className="flex flex-col md:flex-row md:items-start md:gap-6">

                    <div className="flex-1">
                        <div className="flex justify-between items-start gap-4 mb-3">
                             <div className="flex-1">
                                <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500 block mb-3">
                                    {item.category}
                                </span>
                                <h4 className="text-2xl font-sans font-bold text-black leading-tight">
                                    {item.brand || 'Ismeretlen márka'}
                                </h4>
                             </div>

                             <div className="flex flex-col items-end gap-3 shrink-0 md:hidden">
                                {isPerfectMatch ? (
                                    <div className="flex items-center gap-1.5 px-2 py-1 bg-black text-white text-[10px] font-bold uppercase tracking-widest">
                                        <Star className="w-3 h-3 fill-white" />
                                        Tökéletes egyezés
                                    </div>
                                ) : (
                                    <div className={`flex items-center gap-1 text-[10px] font-medium uppercase tracking-wider ${
                                        isHighConfidence ? 'text-black' : 'text-gray-400'
                                    }`}>
                                        {isHighConfidence ? <Check className="w-3 h-3" /> : <AlertTriangle className="w-3 h-3" />}
                                        {getConfidenceText(item.confidence)} bizt.
                                    </div>
                                )}
                                {isPerfectMatch && item.imageUrl && (
                                    <ImageWithFallback 
                                        src={item.imageUrl} 
                                        alt={item.brand} 
                                        className="w-32 h-32 bg-white p-2 object-contain border border-gray-100"
                                    />
                                )}
                             </div>
                        </div>

                        <p className="text-sm font-normal text-gray-600 leading-relaxed w-full">
                          {item.description}
                        </p>

                        {item.materials && item.materials.length > 0 && (
                            <div className="mt-4 pt-4 border-t border-gray-100">
                                <span className="text-[10px] font-bold uppercase tracking-widest text-black block mb-2">ANYAGOK</span>
                                <p className="text-sm font-normal text-black leading-relaxed">
                                    {item.materials?.join(', ')}
                                </p>
                            </div>
                        )}
                    </div>

                    <div className="hidden md:flex flex-col items-end gap-3 shrink-0">
                        {isPerfectMatch ? (
                            <div className="flex items-center gap-1.5 px-2 py-1 bg-black text-white text-[10px] font-bold uppercase tracking-widest">
                                <Star className="w-3 h-3 fill-white" />
                                Tökéletes egyezés
                            </div>
                        ) : (
                            <div className={`flex items-center gap-1 text-[10px] font-medium uppercase tracking-wider ${
                                isHighConfidence ? 'text-black' : 'text-gray-400'
                            }`}>
                                {isHighConfidence ? <Check className="w-3 h-3" /> : <AlertTriangle className="w-3 h-3" />}
                                {getConfidenceText(item.confidence)} bizt.
                            </div>
                        )}

                        {isPerfectMatch && item.imageUrl && (
                            <ImageWithFallback 
                                src={item.imageUrl} 
                                alt={item.brand} 
                                className="w-32 h-32 bg-white p-2 object-contain border border-gray-100"
                            />
                        )}
                    </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useRef } from 'react';
import { Upload } from 'lucide-react';

interface ImageInputProps {
  onImageSelected: (base64: string, mimeType: string, preview: string) => void;
}

export const ImageInput: React.FC<ImageInputProps> = ({ onImageSelected }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const generateOptimizedPayload = (file: File): Promise<{base64: string, mimeType: string}> => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const maxDim = 640; 
          const quality = 0.6;

          if (width > height && width > maxDim) {
            height = (height * maxDim) / width;
            width = maxDim;
          } else if (height > width && height > maxDim) {
            width = (width * maxDim) / height;
            height = maxDim;
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.drawImage(img, 0, 0, width, height);
            const mimeType = 'image/webp';
            const dataUrl = canvas.toDataURL(mimeType, quality);
            const base64 = dataUrl.split(',')[1];
            resolve({ base64, mimeType });
          } else {
            resolve({ 
                base64: (event.target?.result as string).split(',')[1], 
                mimeType: file.type
            });
          }
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const highResPreview = URL.createObjectURL(file);
    e.target.value = '';
    try {
        const { base64, mimeType } = await generateOptimizedPayload(file);
        onImageSelected(base64, mimeType, highResPreview);
    } catch (error) {
        console.error("Error processing image:", error);
    }
  };

  const triggerSelect = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="w-full">
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        accept="image/*"
        className="hidden"
      />

      <div 
        onClick={triggerSelect}
        className="group relative overflow-hidden rounded-none bg-white hover:bg-gray-50 transition-all duration-500 cursor-pointer p-12 text-center"
      >
        <div className="absolute inset-0 pointer-events-none">
            <svg className="w-full h-full" xmlns="http://www.w3.org/2000/svg">
                <rect 
                    x="1" 
                    y="1" 
                    width="99.5%" 
                    height="99%" 
                    fill="none" 
                    stroke="rgba(10,10,10,0.2)" 
                    strokeWidth="1" 
                    strokeDasharray="6 6" 
                    className="group-hover:stroke-black transition-colors duration-500"
                />
            </svg>
        </div>

        <div className="relative z-10 flex flex-col items-center gap-5">
          <div className="w-16 h-16 rounded-full border border-black/10 flex items-center justify-center group-hover:scale-105 group-hover:border-black transition-all duration-500">
            <Upload className="w-6 h-6 text-gray-400 group-hover:text-black transition-colors" />
          </div>
          <div>
            <h3 className="text-xl font-sans font-medium text-black mb-2">Kép Feltöltése</h3>
            <p className="text-sm text-gray-500 font-normal">
              Készíts fotót vagy válassz a galériából
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

