import { GoogleGenAI } from "@google/genai";
import { AnalysisResult, FashionItem } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Using Gemini 3 Pro Preview - currently the most advanced Pro tier model available via API
const MODEL_PRO = "gemini-3-pro-preview";

const SYSTEM_INSTRUCTION = `Te egy világklasszis divatszakértő és brand-nyomozó vagy. 
Feladatod: A feltöltött kép alapján azonosítani a ruhadarabok pontos márkáját és modelljét.
Használd a Google Search eszközt a vizuális jegyek (logók, minták, szabásvonalak) ellenőrzéséhez.
Ha egy darab egyedi vagy nem azonosítható, jelöld 'Egyedi' vagy 'Ismeretlen' jelzéssel.
Csak valódi divatmárkákkal foglalkozz.`;

const PROMPT_TEXT = `Végezz mélyelemzést a képen látható ruházaton. 

KÖVETELMÉNYEK:
1. KERESÉS: Használd a Google keresőt a brand beazonosításához. Keress rá a leírásra: pl. "black double breasted blazer with gold lion buttons brand".
2. PONTOSSÁG: 
   - 'Perfect': Ha a termék 100% azonosítható (pl. hírességen látható, vagy egyedi márka-specifikus jegyei vannak).
   - 'High': Ha a stílus és a részletek alapján nagy valószínűséggel megvan a márka.
3. RÉSZLETEK: Írd le az anyagösszetételt, a stílust (pl. Avant-garde, Minimalist) és a kollekciót, ha látható.

VÁLASZ: RAW JSON formátum.
Struktúra: 
{ 
  "items": [{ "category", "brand", "confidence", "description", "materials", "imageUrl", "shoppingQuery" }], 
  "styleSummary": "Egy rövid, 1-2 mondatos magyar nyelvű összefoglaló az outfit stílusáról." 
}`;

async function generateWithModel(model: string, base64Image: string, mimeType: string) {
    const response = await ai.models.generateContent({
        model: model,
        contents: {
            parts: [
                { inlineData: { data: base64Image, mimeType: mimeType } },
                { text: PROMPT_TEXT },
            ],
        },
        config: {
            tools: [{ googleSearch: {} }],
            systemInstruction: SYSTEM_INSTRUCTION,
            temperature: 0.1, 
            thinkingConfig: { thinkingBudget: 32768 }, 
            maxOutputTokens: 16384,
        },
    });
    return response;
}

function processResponse(response: any): AnalysisResult {
    if (!response || !response.text) {
        throw new Error("Az AI nem tudott választ generálni. Kérjük, próbálkozzon egy másik képpel.");
    }

    let textResponse = response.text;

    try {
        const firstBrace = textResponse.indexOf('{');
        const lastBrace = textResponse.lastIndexOf('}');

        if (firstBrace !== -1 && lastBrace !== -1) {
            textResponse = textResponse.substring(firstBrace, lastBrace + 1);
        }

        const parsedResult = JSON.parse(textResponse) as AnalysisResult;

        if (!parsedResult.items || parsedResult.items.length === 0) {
            throw new Error("Nem sikerült divatcikket azonosítani a képen.");
        }

        parsedResult.items = parsedResult.items.map((item: any) => ({
            ...item,
            brand: item.brand || "Ismeretlen",
            confidence: item.confidence || "Low",
            materials: Array.isArray(item.materials) ? item.materials : (item.materials ? [item.materials] : [])
        }));

        return parsedResult;
    } catch (error) {
        console.error("Parse error:", error);
        throw new Error("Hiba történt az adatok feldolgozásakor. Kérjük, próbálja újra.");
    }
}

export const analyzeFashionImage = async (base64Image: string, mimeType: string): Promise<AnalysisResult> => {
    try {
        const response = await generateWithModel(MODEL_PRO, base64Image, mimeType);
        return processResponse(response);
    } catch (error: any) {
        throw error;
    }
};

