import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { ImageInput } from './components/ImageInput';
import { AnalysisResult } from './components/AnalysisResult';
import { LoadingOverlay } from './components/LoadingOverlay';
import { analyzeFashionImage } from './services/geminiService';
import { AnalysisResult as ResultType, ImageFile } from './types';
import { RefreshCcw, X, AlertTriangle, ArrowRight } from 'lucide-react';
import { LogoIcon } from './components/LogoIcon';

const App: React.FC = () => {
  const [currentImage, setCurrentImage] = useState<ImageFile | null>(null);
  const [analysisResult, setAnalysisResult] = useState<ResultType | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isDelayed, setIsDelayed] = useState(false);

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isLoading && progress >= 95) {
      timer = setTimeout(() => {
        setIsDelayed(true);
      }, 3000); 
    }
    return () => clearTimeout(timer);
  }, [progress, isLoading]);

  const handleImageSelected = (base64: string, mimeType: string, preview: string) => {
    setCurrentImage({ base64, mimeType, preview });
    setAnalysisResult(null);
    setError(null);
  };

  const handleScan = async () => {
    if (!currentImage) return;

    setIsLoading(true);
    setIsDelayed(false);
    setError(null);
    setProgress(0);

    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 98) return 98;
        let increment = prev < 40 ? 1.5 : prev < 90 ? 0.3 : 0.05;
        const next = prev + increment;
        return next;
      });
    }, 150);

    try {
      // Gemini 3 Pro with thinking can take time, so we allow for a quality-first delay
      const result = await analyzeFashionImage(currentImage.base64, currentImage.mimeType);

      setProgress(100);
      setTimeout(() => {
        setAnalysisResult(result);
        setIsLoading(false);
      }, 800);
    } catch (err: any) {
      setError(err.message || "Az elemzés sikertelen volt.");
      setIsLoading(false);
    } finally {
      clearInterval(progressInterval);
    }
  };

  const handleReset = () => {
    setCurrentImage(null);
    setAnalysisResult(null);
    setError(null);
    setProgress(0);
    setIsDelayed(false);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col font-sans text-black selection:bg-black selection:text-white">
      <Header />

      <main 
        className={`max-w-screen-md mx-auto px-6 pb-20 flex-grow w-full flex flex-col ${!currentImage ? 'justify-center items-center h-[80vh]' : 'pt-12'}`}
      >

        {!currentImage && (
          <div className="text-center space-y-8 animate-in fade-in zoom-in-95 duration-1000">
            <h2 className="text-5xl md:text-7xl font-serif font-black tracking-tighter leading-[0.9] text-black">
              AZONOSÍTSD<br/><span className="italic font-light">MINDEN</span> RÉSZLETET.
            </h2>
            <p className="text-gray-400 font-light max-w-sm mx-auto tracking-wide text-sm">
              Tölts fel egy fotót, és szakértői AI rendszerünk a Google adatbázisa segítségével megkeresi a pontos márkát.
            </p>
            <div className="pt-4">
                <ImageInput onImageSelected={handleImageSelected} />
            </div>
          </div>
        )}

        {currentImage && (
          <div className="w-full space-y-16">
            <div className="relative group max-w-lg mx-auto overflow-hidden shadow-2xl transition-transform duration-700 hover:scale-[1.01]">
              <img 
                src={currentImage.preview} 
                alt="Analysis target" 
                className={`w-full h-auto grayscale-[0.2] transition-opacity duration-1000 ${isLoading ? 'opacity-40' : 'opacity-100'}`}
              />

              {isLoading && <LoadingOverlay progress={Math.floor(progress)} showDelayedMessage={isDelayed} />}

              {!isLoading && !analysisResult && (
                 <button 
                 onClick={handleReset}
                 className="absolute top-6 right-6 p-3 bg-white/90 backdrop-blur-sm text-black hover:bg-black hover:text-white transition-all duration-300 z-10 rounded-full"
                 aria-label="Törlés"
               >
                 <X className="w-4 h-4" />
               </button>
              )}
            </div>

            {error && (
              <div className="border border-red-100 bg-red-50/30 p-8 flex items-start gap-6 animate-in slide-in-from-top-4 duration-500">
                <AlertTriangle className="w-6 h-6 text-red-500 shrink-0 mt-1" />
                <div>
                  <h4 className="font-bold text-black uppercase tracking-widest text-xs mb-2">Hiba történt</h4>
                  <p className="text-gray-600 font-light">{error}</p>
                  <button onClick={handleReset} className="mt-6 text-[10px] font-black uppercase tracking-[0.2em] border-b border-black pb-1">Új próbálkozás</button>
                </div>
              </div>
            )}

            {analysisResult && !isLoading && (
              <AnalysisResult result={analysisResult} />
            )}

            {!isLoading && !analysisResult && (
                <div className="flex justify-center">
                    <button 
                        onClick={handleScan}
                        className="group flex items-center gap-8 py-6 px-12 bg-black text-white hover:bg-gray-900 transition-all duration-500 animate-in fade-in slide-in-from-bottom-6"
                    >
                        <span className="text-xs font-bold uppercase tracking-[0.4em]">Elemzés indítása</span>
                        <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-2" />
                    </button>
                </div>
            )}

            {analysisResult && !isLoading && (
               <div className="pt-20 border-t border-gray-100">
                    <button 
                        onClick={handleReset}
                        className="w-full py-8 border border-black text-black hover:bg-black hover:text-white transition-all duration-500 flex items-center justify-center gap-4 group"
                    >
                        <RefreshCcw className="w-4 h-4 group-hover:rotate-180 transition-transform duration-700" />
                        <span className="text-xs font-bold uppercase tracking-[0.3em]">Új Look Szkennelése</span>
                    </button>
               </div>
            )}
          </div>
        )}

      </main>

      <footer className="w-full py-12 text-center">
          <p className="text-[9px] text-gray-300 font-bold uppercase tracking-[0.5em]">
              Powered by Google Gemini 3 Pro • <a href="https://kisskatal.in" className="text-gray-400 hover:text-black transition-colors border-b border-transparent hover:border-black">kisskatal.in</a>
          </p>
      </footer>
    </div>
  );
};

